import {MASKS,xpQuarters,roleQuarters,maskPixels} from './smart-model.js';
export function xpAtlas(image,canvasFactory=()=>document.createElement('canvas')){const canvas=canvasFactory();canvas.width=128;canvas.height=96;const ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;MASKS.forEach((mask,index)=>xpQuarters(mask).forEach(([x,y],q)=>ctx.drawImage(image,x*16,y*16,16,16,index%8*16+q%2*8,Math.floor(index/8)*16+(q>>1)*8,8,8)));return canvas;}
export function roleAtlas(roles,images,canvasFactory=()=>document.createElement('canvas')){const canvas=canvasFactory();canvas.width=128;canvas.height=96;const ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;MASKS.forEach((mask,index)=>roleQuarters(mask).forEach((role,q)=>{const t=roles[role];if(!t)throw new Error('Assign every terrain role, including the four inside corners.');const half=t.size/2;ctx.drawImage(images.get(t.a),t.sx+(q%2)*half,t.sy+(q>>1)*half,half,half,index%8*16+(q%2)*8,Math.floor(index/8)*16+(q>>1)*8,8,8);}));return canvas;}
export function maskedCanvas(image,mask,canvasFactory=()=>document.createElement('canvas')){const c=canvasFactory();c.width=image.width;c.height=image.height;const ctx=c.getContext('2d'),im=ctx.createImageData(c.width,c.height);im.data.set(maskPixels(image.data,mask));ctx.putImageData(im,0,0);return c;}
export function drawNineSlice(ctx,image,o){const b=o.nineSlice||16,w=o.w*16,h=o.h*16;if(w<b*2||h<b*2||o.sw<b*3||o.sh<b*3){ctx.drawImage(image,o.sx,o.sy,o.sw,o.sh,0,0,w,h);return;}const xs=[0,b,w-b,w],ys=[0,b,h-b,h],sx=[o.sx,o.sx+b,o.sx+o.sw-b],sy=[o.sy,o.sy+b,o.sy+o.sh-b];for(let row=0;row<3;row++)for(let col=0;col<3;col++){const dw=xs[col+1]-xs[col],dh=ys[row+1]-ys[row],sw=col===1?o.sw-2*b:b,sh=row===1?o.sh-2*b:b;for(let y=0;y<dh;y+=sh)for(let x=0;x<dw;x+=sw){const cw=Math.min(sw,dw-x),ch=Math.min(sh,dh-y);ctx.drawImage(image,sx[col],sy[row],cw,ch,xs[col]+x,ys[row]+y,cw,ch);}}}
